import { clamp } from './math';
import { padStart } from './pad';
import type { Row } from './types';

export function cell(value: string, width: number): string {
  return padStart(value, clamp(width, 1, 40));
}

export function formatRow(row: Row, widths: number[]): string {
  const parts: string[] = [];
  let total = 0;
  for (const [i, value] of row.values.entries()) {
    const width = widths[i] ?? 8;
    const text = cell(value, width);
    parts.push(text);
    total += text.length;
  }
  const sep = row.dense ? '|' : ' | ';
  const line = parts.join(sep);
  total += sep.length * (parts.length - 1);
  console.debug('row width', total);
  return line;
}

